const input = $input.first().json || {};

function nowIso() {
  return new Date().toISOString();
}

function normalizeString(value) {
  if (value === undefined || value === null) return "";
  return String(value).trim();
}

function normalizeCurrency(value) {
  return normalizeString(value).toUpperCase();
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        success: false,
        component_id: "C2-H",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        payment_request: null,
        provider_handoff: null,
        manual_review_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};
const payload = source.payload || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C2-H will not prepare payment request when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "prepare_payment_request") {
  return fail({
    code: "PAYMENT_NOT_REQUESTED",
    message: "source.next_action is not prepare_payment_request.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.provider) {
  return fail({
    code: "MISSING_PROVIDER",
    message: "config.provider is required."
  });
}

if (!config.mode) {
  return fail({
    code: "MISSING_MODE",
    message: "config.mode is required."
  });
}

if (!config.payment_type) {
  return fail({
    code: "MISSING_PAYMENT_TYPE",
    message: "config.payment_type is required."
  });
}

const provider = normalizeString(config.provider).toLowerCase();
const mode = normalizeString(config.mode).toLowerCase();
const paymentType = normalizeString(config.payment_type).toLowerCase();

const supportedProviders = ["razorpay", "stripe", "paypal", "wise", "manual"];
const supportedModes = ["payment_link_handoff", "invoice_handoff", "manual_payment_handoff", "manual_review"];
const supportedPaymentTypes = ["advance_payment", "full_payment", "deposit", "invoice_payment", "manual_transfer"];

if (!supportedProviders.includes(provider)) {
  return fail({
    code: "UNSUPPORTED_PROVIDER",
    message: "config.provider is not supported in C2-H v1.",
    details: [{ provider, supported_providers: supportedProviders }]
  });
}

if (!supportedModes.includes(mode)) {
  return fail({
    code: "UNSUPPORTED_MODE",
    message: "config.mode is not supported in C2-H v1.",
    details: [{ mode, supported_modes: supportedModes }]
  });
}

if (!supportedPaymentTypes.includes(paymentType)) {
  return fail({
    code: "UNSUPPORTED_PAYMENT_TYPE",
    message: "config.payment_type is not supported in C2-H v1.",
    details: [{ payment_type: paymentType, supported_payment_types: supportedPaymentTypes }]
  });
}

if (Array.isArray(config.allowed_payment_types) && config.allowed_payment_types.length > 0) {
  if (!config.allowed_payment_types.includes(paymentType)) {
    return fail({
      code: "PAYMENT_TYPE_NOT_ALLOWED",
      message: "config.payment_type is not allowed by config.allowed_payment_types.",
      details: [
        {
          payment_type: paymentType,
          allowed_payment_types: config.allowed_payment_types
        }
      ]
    });
  }
}

if (config.approval_status_required === true) {
  const approved = source.approved_action?.approved === true;
  if (!approved) {
    return fail({
      code: "PAYMENT_NOT_APPROVED",
      message: "Approved action is required before preparing payment provider handoff.",
      details: [{ approved_action: source.approved_action || null }]
    });
  }
}

const amount = Number(payload.amount);
const currency = normalizeCurrency(payload.currency);
const customerEmail = normalizeString(payload.customer_email);
const customerName = normalizeString(payload.customer_name);
const customerPhone = normalizeString(payload.customer_phone);
const company = normalizeString(payload.company);
const description = normalizeString(payload.description);
const referenceId = normalizeString(payload.reference_id);

if (!Number.isFinite(amount) || amount <= 0) {
  return fail({
    code: "MISSING_OR_INVALID_AMOUNT",
    message: "input.payload.amount must be a positive number."
  });
}

if (!currency) {
  return fail({
    code: "MISSING_CURRENCY",
    message: "input.payload.currency is required."
  });
}

if (!customerEmail && provider !== "wise" && provider !== "manual") {
  return fail({
    code: "MISSING_CUSTOMER_EMAIL",
    message: "input.payload.customer_email is required for provider handoff."
  });
}

if (Array.isArray(config.allowed_currencies) && config.allowed_currencies.length > 0) {
  const allowedCurrencies = config.allowed_currencies.map(item => normalizeCurrency(item));
  if (!allowedCurrencies.includes(currency)) {
    return fail({
      code: "CURRENCY_NOT_ALLOWED",
      message: "input.payload.currency is not allowed by config.allowed_currencies.",
      details: [
        {
          currency,
          allowed_currencies: allowedCurrencies
        }
      ]
    });
  }
}

if (provider === "razorpay" && mode !== "payment_link_handoff") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Razorpay v1 supports payment_link_handoff mode only.",
    details: [{ provider, mode }]
  });
}

if (provider === "stripe" && mode !== "payment_link_handoff") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Stripe v1 supports payment_link_handoff mode only.",
    details: [{ provider, mode }]
  });
}

if (provider === "paypal" && mode !== "invoice_handoff") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "PayPal v1 supports invoice_handoff mode only.",
    details: [{ provider, mode }]
  });
}

if (provider === "wise" && mode !== "manual_payment_handoff") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Wise v1 supports manual_payment_handoff mode only.",
    details: [{ provider, mode }]
  });
}

if (provider === "manual" && mode !== "manual_review") {
  return fail({
    code: "INVALID_PROVIDER_MODE",
    message: "Manual provider supports manual_review mode only.",
    details: [{ provider, mode }]
  });
}

const paymentTerms = config.payment_terms || {};
const dueInDays = Number(paymentTerms.due_in_days || 7);
const dueAt = new Date(Date.now() + dueInDays * 24 * 60 * 60 * 1000).toISOString();

const paymentRequest = {
  provider,
  mode,
  status: "ready",
  payment_type: paymentType,
  amount,
  currency,
  description: description || null,
  reference_id: referenceId || null,
  customer: {
    name: customerName || null,
    email: customerEmail || null,
    phone: customerPhone || null,
    company: company || null
  },
  payment_terms: {
    due_in_days: dueInDays,
    due_at: dueAt,
    allow_partial_payment: paymentTerms.allow_partial_payment === true,
    send_reminder: paymentTerms.send_reminder === true
  },
  requires_approval: config.requires_approval === true,
  approval_status_required: config.approval_status_required === true,
  prepared_at: nowIso()
};

let providerPayload = {};
let providerHandoff = null;
let manualReviewHandoff = null;
let nextAction = config.default_next_action || "payment_request_ready";

if (mode === "payment_link_handoff") {
  if (provider === "razorpay") {
    providerPayload = {
      provider,
      action: "create_payment_link",
      amount,
      currency,
      description,
      reference_id: referenceId,
      customer: {
        name: customerName,
        email: customerEmail,
        contact: customerPhone
      },
      options: {
        accept_partial: paymentTerms.allow_partial_payment === true,
        expire_by: dueAt,
        reminder_enable: paymentTerms.send_reminder === true
      }
    };
  }

  if (provider === "stripe") {
    providerPayload = {
      provider,
      action: "create_payment_link_or_checkout_session",
      amount,
      currency,
      description,
      reference_id: referenceId,
      customer_email: customerEmail,
      metadata: {
        customer_name: customerName,
        company,
        payment_type: paymentType,
        reference_id: referenceId
      }
    };
  }
}

if (mode === "invoice_handoff") {
  if (provider === "paypal") {
    providerPayload = {
      provider,
      action: "create_invoice",
      amount,
      currency,
      description,
      reference_id: referenceId,
      recipient: {
        name: customerName,
        email: customerEmail
      },
      invoice_detail: {
        currency_code: currency,
        note: description,
        payment_term: {
          term_type: "DUE_ON_DATE_SPECIFIED",
          due_date: dueAt
        }
      }
    };
  }
}

if (mode === "manual_payment_handoff") {
  providerPayload = {
    provider,
    action: "prepare_manual_payment_instructions",
    amount,
    currency,
    description,
    reference_id: referenceId,
    customer: {
      name: customerName,
      email: customerEmail,
      phone: customerPhone,
      company
    },
    manual_payment_instructions: config.manual_payment_instructions || {}
  };
}

if (["payment_link_handoff", "invoice_handoff", "manual_payment_handoff"].includes(mode)) {
  providerHandoff = {
    next_component: `${provider}_payment_adapter`,
    input: {
      success: true,
      component_id: "C2-H",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "payment_provider_request",
      payment_request: paymentRequest,
      provider_payload: providerPayload,
      source_result: source,
      error: null,
      next_action: "create_payment_request"
    },
    config: {
      provider,
      adapter_required: true,
      default_next_action: "track_payment_status"
    }
  };

  nextAction = config.default_next_action || "create_payment_provider_handoff";
}

if (mode === "manual_review") {
  manualReviewHandoff = {
    next_component: "C5-E",
    input: {
      success: true,
      component_id: "C2-H",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: "manual_payment_review",
      payment_request: paymentRequest,
      source_result: source,
      error: null,
      next_action: "manual_review"
    },
    config: {
      queue_type: "payment_review",
      review_reason: "Manual payment review required.",
      reviewer_email: config.reviewer_email || "shwetabh.singh@lexnovahq.com",
      owner: "ops",
      priority: config.priority || "normal",
      allowed_actions: ["approve_payment_request", "edit_payment_request", "reject_payment_request", "request_more_info"],
      default_next_action: "notify_reviewer"
    }
  };

  nextAction = "manual_review";
}

return [
  {
    json: {
      success: true,
      component_id: "C2-H",
      component_version: "v1",
      event_id: source.event_id || null,
      event_type: source.event_type || null,
      payment_request: paymentRequest,
      provider_handoff: providerHandoff,
      manual_review_handoff: manualReviewHandoff,
      source_result: source,
      error: null,
      next_action: nextAction
    }
  }
];
